import core.game.world.map.*;import core.game.world.map.build.*;import core.game.node.scenery.Scenery;
public class Support{
 static Map input;static Region region;static List<RegionChunk>original;static List<boolean[][]>old,projectile;static Map<String,Scenery>nodes;static List<Object>events;static Map<String,Integer>calls;static List<byte[][][]>maps;
 public static class Failure extends RuntimeException{}
 static int n(Object x){return((Number)x).intValue();}static int v(Map m,String k,int d){return m.get(k)==null?d:n(m.get(k));}static boolean b(Map m,String k){return Boolean.TRUE.equals(m.get(k));}
 static Location loc(Object x){List a=(List)x;return new Location(n(a.get(0)),n(a.get(1)),n(a.get(2)));}static Object coords(Location l){return Arrays.asList(l.getX(),l.getY(),l.getZ());}
 static Map<String,Object>map(Object...p){Map<String,Object>m=new TreeMap<>();for(int i=0;i<p.length;i+=2)m.put((String)p[i],p[i+1]);return m;}
 public static void emit(String name,Object...args){List<Object>row=new ArrayList<>();row.add(name);Collections.addAll(row,args);events.add(row);int call=calls.merge(name,1,Integer::sum);for(Object r:(List)input.getOrDefault("hooks",new ArrayList<>())){Map h=(Map)r;if(name.equals(h.get("event"))&&call==v(h,"at",1))for(Object a:(List)h.get("actions"))act((Map)a);}if(name.equals(input.get("failEvent"))&&call==v(input,"failAt",1))throw new Failure();}
 public static int archive(String name){emit("archive",name);return v(input,name.startsWith("m")?"mapId":"landId",5);}
 static byte[]bytes(Object value){if(value==null)return null;String h=(String)value;byte[]a=new byte[h.length()/2];for(int i=0;i<a.length;i++)a[i]=(byte)Integer.parseInt(h.substring(i*2,i*2+2),16);return a;}
 public static byte[]mapBytes(int id){emit("mapBytes",id);return bytes(input.getOrDefault("mapData","00"));}
 public static int[]keys(int id){emit("keys",id);return new int[]{-1,0,Integer.MIN_VALUE,Integer.MAX_VALUE};}
 public static byte[]landBytes(int id,int[]keys){List<Integer>k=new ArrayList<>();for(int v:keys)k.add(v);emit("landBytes",id,k);return bytes(input.getOrDefault("landData","00000000"));}
 static int mapId(byte[][][]m){for(int i=0;i<maps.size();i++)if(maps.get(i)==m)return i;maps.add(m);return maps.size()-1;}
 public static void parseMap(Region r,byte[][][]m,ByteBuffer bytes){emit("mapParse",mapId(m),bytes.remaining());m[0][0][0]=1;}
 public static void parseLand(Region r,RegionChunk[][][]chunks,byte[][][]m,ByteBuffer bytes,boolean build){emit("landParse",mapId(m),bytes.remaining(),build,chunks==null);r.setObjectCount(r.getObjectCount()+1);m[0][0][1]=2;}
 public static void clip(Region r,RegionChunk[][][]chunks,byte[][][]m){emit("clip",mapId(m),chunks==null);m[0][0][2]=3;}
 static String name(Scenery h){for(String k:nodes.keySet())if(nodes.get(k)==h)return k;return null;}
 public static Scenery object(int x,int y,int z,int id,int shape){emit("object",Arrays.asList(x,y,z),id,shape);Object actual=input.getOrDefault("actual","real");return actual==null?null:nodes.get(actual);}
 public static void remove(Scenery h){emit("remove",name(h));}public static void add(Scenery h){emit("add",name(h));}
 static Object act(Map a){switch((String)a.get("op")){
 case"load":if(a.containsKey("build"))Region.load(region,b(a,"build"));else Region.load(region);break;
 case"state":if(a.containsKey("loaded"))region.setLoaded(b(a,"loaded"));if(a.containsKey("build"))region.setBuild(b(a,"build"));if(a.containsKey("flags"))region.hasFlags=b(a,"flags");break;
 case"nullChunks":region.chunks=null;break;
 case"clear":(b(a,"add")?region.addSceneries:region.removeSceneries).clear();break;
 case"push":(b(a,"add")?region.addSceneries:region.removeSceneries).add(nodes.get(a.get("node")));break;
 case"erase":(b(a,"add")?region.addSceneries:region.removeSceneries).remove(n(a.get("index")));break;
 case"input":input.put(a.get("key"),a.get("value"));break;default:throw new AssertionError(a);
 }return null;}
 static Object snapshot()throws Exception{List<Object>reset=new ArrayList<>(),marked=new ArrayList<>(),proj=new ArrayList<>();for(int i=0;i<original.size();i++){RegionChunk c=original.get(i);if(c.flags.landscape!=old.get(i))reset.add(i);if(c.flags.landscape[0][0])marked.add(i);if(c.projectile.landscape!=projectile.get(i))proj.add(i);}List<String>adds=new ArrayList<>(),removes=new ArrayList<>();for(Scenery h:region.addSceneries)adds.add(name(h));for(Scenery h:region.removeSceneries)removes.add(name(h));List<String>hashes=new ArrayList<>();for(byte[][][]m:maps){MessageDigest hash=MessageDigest.getInstance("SHA-256");for(byte[][]plane:m)for(byte[]row:plane)hash.update(row);StringBuilder s=new StringBuilder();for(byte x:hash.digest())s.append(String.format("%02x",x&255));hashes.add(s.toString());}return map("loaded",region.isLoaded(),"build",region.isBuild(),"flags",region.hasFlags,"count",region.getObjectCount(),"chunksNull",region.chunks==null,"reset",reset,"marked",marked,"projectileChanged",proj,"add",adds,"remove",removes,"maps",hashes,"events",new ArrayList<>(events));}
 static void setup(Map i){input=new HashMap(i);region=i.containsKey("template")?new DynamicRegion(n(i.get("template"))):new Region();region.setLoaded(b(i,"loaded"));region.setBuild(b(i,"build"));region.hasFlags=b(i,"flags");region.setObjectCount(v(i,"count",0));original=new ArrayList<>();old=new ArrayList<>();projectile=new ArrayList<>();for(int x=0;x<8;x++)for(int y=0;y<8;y++)for(int z=0;z<4;z++){RegionChunk c=region.chunks[x][y][z];original.add(c);old.add(c.flags.landscape);projectile.add(c.projectile.landscape);}for(Object r:(List)i.getOrDefault("nulls",new ArrayList<>())){List a=(List)r;region.chunks[n(a.get(0))][n(a.get(1))][n(a.get(2))]=null;}if(b(i,"nullChunks"))region.chunks=null;nodes=new TreeMap<>();nodes.put("a",new Scenery(10,new Location(3200,3200,0),0));nodes.put("b",new Scenery(11,new Location(3201,3200,0),1));nodes.put("c",new Scenery(12,new Location(3202,3200,0),2));nodes.put("real",new Scenery(99,new Location(3203,3200,0),3));for(Object k:(List)i.getOrDefault("remove",Arrays.asList("a","b")))region.removeSceneries.add(nodes.get(k));for(Object k:(List)i.getOrDefault("add",Arrays.asList("c")))region.addSceneries.add(nodes.get(k));events=new ArrayList<>();calls=new HashMap<>();maps=new ArrayList<>();}
 static Object errors(String text){List<Object>out=new ArrayList<>();for(String line:text.split("\\R")){if(line.startsWith("java.lang.Throwable: Failed parsing region "))out.add(Arrays.asList("landscape",Integer.parseInt(line.substring("java.lang.Throwable: Failed parsing region ".length(),line.indexOf('!')))));else if(line.startsWith("oracle.Support$Failure"))out.add(Arrays.asList("outer","Binding"));else if(line.startsWith("java.lang.NullPointerException"))out.add(Arrays.asList("outer","Null"));else if(line.startsWith("java.util.ConcurrentModificationException"))out.add(Arrays.asList("outer","ConcurrentModification"));}return out;}
 public static void main(String[]args)throws Exception{ByteArrayOutputStream err=new ByteArrayOutputStream();System.setErr(new PrintStream(err,true,"UTF-8"));try(BufferedReader r=new BufferedReader(new InputStreamReader(System.in,java.nio.charset.StandardCharsets.UTF_8));BufferedWriter w=new BufferedWriter(new OutputStreamWriter(System.out,java.nio.charset.StandardCharsets.UTF_8))){String line;while((line=r.readLine())!=null){JSONObject c=(JSONObject)new JSONParser().parse(line);setup(c);List<Object>out=new ArrayList<>();for(Object a:(List)c.get("actions")){events.clear();err.reset();act((Map)a);Map<String,Object>s=(Map)snapshot();s.put("errors",errors(err.toString("UTF-8")));out.add(s);}c.put("expected",out);JSONValue.writeJSONString(c,w);w.newLine();w.flush();}}}
}
